/** Concrete unit instances qualify every supplied cut on immutable common barriers. */
public final class ContextUniversalInstantiatedUnitRoundsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits limits(int fact){return ContextUniversalSignedFixedApplicationRoundsRunner.limits(fact);}
    static Result run(Snapshot x,List<Snapshot> a,Packet p,Map<Cut,PrivatePool> pools,Exchange e,int fact,int rounds){return ContextUniversalSignedUnitRounds.runInstantiatedUnits(x,a,p,pools,e,limits(fact),rounds,WORK);}
    static Result stable(Result r,Exchange e){ContextUniversalSignedFixedApplicationRoundsRunner.stable(r,e);for(Round n:r.history)for(ContextUniversalFrozenConstraints.Result c:n.checks.values())require(c.instantiatedUnits,"explicit mode in EVERY cut/round");return r;}
    static void incomplete(Result r,String phase,int completed){ContextUniversalSignedFixedApplicationRoundsRunner.incomplete(r,phase,completed,"atomic instantiated-unit refusal");++checks;}
    static Item item(Packet p,String name){return p.items.stream().filter(i->i.atom.predicate.equals(name)).findFirst().get();}
    static void refuted(Result r,int round){require(r.status==Status.REFUTED&&r.completedRounds==round-1&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&!r.refutations.isEmpty(),r.phase+": "+r.reason);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Refutation f:r.refutations.values()){require(f.round==round&&!f.proofs.isEmpty(),"actual barrier rejection");for(Proof p:f.proofs){require(p.clause==null,"only empty rejection roots");ContextUniversalInstantiatedUnitApplicationsRunner.audit(p,seen);}}}
    static void fixed()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u,u); !@v q(v);"),a=bind(false,"!@x p(x,1)&&q(x)->r(x);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> list=Collections.singletonList(a);
        incomplete(ContextUniversalSignedUnitRounds.runGroundedMixed(x,list,p,Collections.emptyMap(),null,limits(1),8,WORK),"transfers",0);Result r=stable(run(x,list,p,Collections.emptyMap(),null,1,8),null);require(r.completedRounds==2&&r.history.get(0).commonChanged&&item(r.output.packet,"r").proofs.stream().allMatch(s->s.depth==1&&s.sources.size()==3),"all-symbolic actual instances produce fixed1 and requalify next barrier");require(stable(run(x,list,r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"exact continuation stable1");incomplete(run(x,list,p,Collections.emptyMap(),null,1,1),"round-limit",1);incomplete(run(x,list,p,Collections.emptyMap(),null,0,8),"transfers",0);
        Result old=ContextUniversalSignedUnitRounds.runGroundedMixed(x,list,p,Collections.emptyMap(),null,limits(16),8,WORK);require(old.status==Status.STABLE_UNIT_POOLS&&item(old.output.packet,"r").proofs.stream().allMatch(s->s.depth==2)&&old.history.stream().flatMap(n->n.checks.values().stream()).noneMatch(c->c.instantiatedUnits),"old scheduler preserves binary2/explicit scope");Result improved=stable(run(x,list,old.output.packet,old.output.privatePools,old.symbolicOutput,16,8),old.symbolicOutput);require(improved.completedRounds==2&&improved.history.get(0).commonChanged&&improved.history.get(0).input.items.size()==improved.history.get(0).barrier.packet.items.size()&&item(improved.output.packet,"r").proofs.stream().allMatch(s->s.depth==1)&&item(old.output.packet,"r").proofs.stream().allMatch(s->s.depth==2),"same-Source grade-only fixed improvement forces all-cut requalification, old input immutable");
        Snapshot opinion=bind(false,"!~r(1);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,opinion),Arrays.asList(opinion,a))){Result no=run(x,order,p,Collections.emptyMap(),null,1,8);refuted(no,2);require(no.refutations.get(Cut.of(opinion)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"peer opposite fixed opinion empty2/four Sources only next barrier");}
        Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,opinion),WORK);Result direct=run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,1,8);refuted(direct,1);Snapshot bad=bind(false,"!bad(1)||other(1);");incomplete(run(x,Arrays.asList(group,bad),p,Collections.emptyMap(),null,16,8),"checks",0);incomplete(run(x,list,ContextPrivateWitnessPoolRunner.common(x),Collections.emptyMap(),r.symbolicOutput,16,8),"preflight",0);incomplete(ContextUniversalSignedUnitRounds.runInstantiatedUnits(x,list,p,Collections.emptyMap(),null,limits(16),8,1),"preflight",0);
        Map<Cut,Packet> outputs=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())outputs.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(r.history.get(1).input,new ArrayList<>(outputs.keySet()),WORK).finish(outputs,WORK).status==FamilyStatus.INCOMPLETE,"stable instantiated pools grant no family STEP/admission");
    }
    static void symbolicAndAlternatives()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u,u); !@v q(v);"),a=bind(false,"!@x @y p(x,1)&&q(x)->~r(x,y);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> list=Collections.singletonList(a);incomplete(ContextUniversalSignedUnitRounds.runGroundedMixed(x,list,p,Collections.emptyMap(),null,limits(1),8,WORK),"symbolic-collection",0);Result r=stable(run(x,list,p,Collections.emptyMap(),null,1,8),null);require(r.completedRounds==2&&!r.history.get(0).commonChanged&&r.history.get(0).symbolicChanged&&r.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.support.depth==1&&u.support.sources.size()==3),"symbolic-only universal1 change forces all-cut barrier");require(stable(run(x,list,r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"symbolic actual continuation stable1");incomplete(run(x,list,p,Collections.emptyMap(),null,0,8),"symbolic-collection",0);
        Result old=ContextUniversalSignedUnitRounds.runGroundedMixed(x,list,p,Collections.emptyMap(),null,limits(16),8,WORK);require(old.status==Status.STABLE_UNIT_POOLS&&old.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.support.depth==2),"actual old universal2 state");Result better=stable(run(x,list,old.output.packet,old.output.privatePools,old.symbolicOutput,16,8),old.symbolicOutput);require(better.completedRounds==2&&!better.history.get(0).commonChanged&&better.history.get(0).symbolicChanged&&old.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.support.depth==2),"symbolic grade-only improvement forces barrier without mutating old receipt");
        Snapshot yes=bind(false,"!r(1,987654);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,yes),Arrays.asList(yes,a))){Result no=run(x,order,p,Collections.emptyMap(),null,1,8);refuted(no,2);Refutation f=no.refutations.get(Cut.of(yes));require(f.proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"unmentioned universal-head value rejects on next round empty2/four Sources");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof v:f.proofs)ContextUniversalInstantiatedUnitApplicationsRunner.audit(v,seen);require(seen.stream().anyMatch(v->v.instantiatedUnitRecipe&&!v.instantiatedDonors.isEmpty()),"flattened historical universal proof preserves real instances and parents");}
        Snapshot bridge=bind(false,"!@u @v ~r(u,v)->~s(u,v);"),end=bind(false,"!s(1,987654);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,bridge,end),Arrays.asList(end,bridge,a))){Result chain=run(x,order,p,Collections.emptyMap(),null,2,8);refuted(chain,3);require(chain.refutations.get(Cut.of(end)).proofs.stream().anyMatch(v->v.support.depth==3&&v.support.sources.size()==5),"universal1 then bridge2 then empty3/five Sources across TWO symbolic barriers");}
        Snapshot loop=bind(false,"!@u @v r(u,v)->r(u,v);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,loop),WORK);Result alts=stable(run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,2,8),null);require(alts.symbolicOutput.units.stream().filter(u->u.clause.literals.get(0).predicate.equals("r")).count()==2&&alts.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.support.depth==2&&u.support.sources.size()==4),"whole Source superset2 stays beside base1 at every barrier");incomplete(run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,1,8),"symbolic-collection",0);
    }
    static void privateAndScope()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u,1); !@u @v p(u,1)&&q(u,1)->~r(u,v);"),a=bind(false,"!$u q(u,1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);Result r=stable(run(x,Collections.singletonList(a),p,pools,null,1,8),null);require(r.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.clause.variables.size()==1&&u.clause.origins.size()==1&&u.support.depth==1&&u.support.sources.size()==3&&u.support.sources.contains(a.primary.get(0).source)),"physical private Origin plus universal head at1 with actual binding");require(r.output.packet.items.size()==1&&pool.common==p&&pool.local.items.stream().noneMatch(i->i.atom.predicate.equals("r")),"raw witnesses withheld, old pool immutable");require(stable(run(x,Collections.singletonList(a),r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"private/symbolic frames resume exactly");incomplete(run(x,Collections.singletonList(a),p,Collections.emptyMap(),null,1,8),"checks",0);
        Snapshot universal=bind(false,"!@u @v r(u,v);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,universal),Arrays.asList(universal,a))){incomplete(run(x,order,p,pools,null,1,8),"symbolic-collection",0);Result no=run(x,order,p,pools,null,2,8);refuted(no,2);require(no.refutations.get(Cut.of(universal)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4&&v.support.sources.contains(a.primary.get(0).source)),"actual private binding requalifies universal opinion, empty2/four Sources after independent reverse-symbolic2 bound");}
        Snapshot positive=bind(false,"!r(John,1);");Result irrelevant=stable(run(x,Arrays.asList(a,positive),p,pools,null,1,8),null);require(irrelevant.status==Status.STABLE_UNIT_POOLS,"rigid private Origin is not an unrelated ordinary named value");
        Snapshot own=bind(false,"!@u p(u,1); !$u q(u,1); !@u @v p(u,1)&&q(u,1)->~r(u,v);");Snapshot anchor=bind(true,"!anchor(1);");Packet ap=ContextPrivateWitnessPoolRunner.common(anchor);PrivatePool raw=ContextWitnessResultTransport.privatePool(ap,anchor,own,WORK);Result local=stable(run(anchor,Collections.singletonList(own),ap,Collections.singletonMap(raw.cut,raw),null,1,8),null);require(local.output.packet.items.size()==1&&local.symbolicOutput.units.isEmpty(),"foreign-only symbolic residual never becomes common X knowledge");
        Snapshot yes=bind(false,"!@u p(u);"),no=bind(false,"!~p(1);");Result independent=stable(run(anchor,Arrays.asList(yes,no),ap,Collections.emptyMap(),null,1,1),null);require(independent.output.packet.items.size()==1&&independent.symbolicOutput.units.isEmpty(),"unrelated anchor cannot communalize sibling opinions");
        Snapshot sx=bind(true,"!anchor(1); !@u p(u); !@v q(v);"),free=bind(false,"!@x p(x)&&q(x)->r(x);");Result ungrounded=stable(run(sx,Collections.singletonList(free),ContextPrivateWitnessPoolRunner.common(sx),Collections.emptyMap(),null,2,8),null);require(ungrounded.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.support.depth==2&&!u.proof.instantiatedUnitRecipe),"free donor arguments retain binary2 scope in new scheduler");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("instantiated-unit-rounds-").toString());fixed();symbolicAndAlternatives();privateAndScope();System.out.println("CONTEXT_UNIVERSAL_INSTANTIATED_UNIT_ROUNDS_PASS checks="+(checks+ContextUniversalSignedFixedApplicationRoundsRunner.checks+ContextUniversalInstantiatedUnitApplicationsRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
